// Verbena & Rust storefront (CScript CForms page)
@Page("Verbena & Rust - Bioluminescent Orchids")
module StorefrontIndex;

import CForms;

Form Build() {
    Form page = new Form("Verbena & Rust");
    page.Add(new Label("Bioluminescent orchids, grown above the waterline."));
    page.Add(new Label("Same-day courier to every enclave above the seawall."));
    page.Add(new Button("Browse the catalog", "/catalog_orchids.csv"));
    return page;
}
